/* Feste Übersetzung der Lerninhalte (fa), maschinell erstellt, nicht von Muttersprachlern geprüft. Code bleibt unverändert. */
(function(r){"use strict";const f=r.SDAkademieFest=r.SDAkademieFest||{};(f["fa"]=f["fa"]||{})["career"]={"Aus der Stellenanzeige einen Bewerbungsplan machen":"ساختن یک برنامهٔ درخواست از اعلان کار","Du leitest passende Belege und Inhalte für deine Bewerbung aus den Anforderungen ab.":"شما مدارک و محتوای مناسب درخواست را از شرط‌ها بیرون می‌کشید.","Angeleitete Tätigkeit als Leitung darstellen":"کار تحت راهنمایی را مدیریت نشان دادن","Falsch: „Ich leitete die Bestellbearbeitung“, obwohl nur angeleitet erfasst wurde. Richtig: „Ich erfasste Bestellungen unter Anleitung.“":"اشتباه: „Ich leitete die Bestellbearbeitung“ (من پردازش سفارش‌ها را رهبری کردم)، در حالی که فقط تحت راهنمایی ثبت شده است. درست: „Ich erfasste Bestellungen unter Anleitung.“ (من سفارش‌ها را تحت راهنمایی ثبت کردم.)","Zertifikat erfinden":"ساختن گواهی‌نامهٔ ساختگی","Falsch: Einen nicht erworbenen Nachweis ergänzen, um eine Lücke zu schließen. Richtig: Tatsächliche Erfahrung und Lernbedarf ehrlich benennen.":"اشتباه: یک مدرک به‌دست‌نیامده را اضافه کنید تا یک کمبود را بپوشانید. درست: تجربهٔ واقعی و نیاز به یادگیری را صادقانه نام ببرید.","Welche Aussage beschreibt Linas Bestellerfahrung korrekt?":"کدام جمله تجربهٔ سفارش لینا را درست توصیف می‌کند؟","Sie bearbeitete Bestellungen vollständig eigenverantwortlich.":"او سفارش‌ها را کاملاً با مسئولیت خودش پردازش کرد.","Sie erfasste Bestellungen unter Anleitung.":"او سفارش‌ها را تحت راهنمایی ثبت کرد.","Sie war für die Freigabe aller Bestellungen zuständig.":"او مسئول تأیید همهٔ سفارش‌ها بود.","Lina nennt ausdrücklich eine angeleitete Erfassung und keine Leitungsaufgabe.":"لینا صریحاً یک ثبت تحت راهنمایی را نام می‌برد، نه یک کار مدیریتی.","Was gehört in die Belegliste?":"چه چیزی در لست مدارک جا دارد؟","Ein echtes Beispiel zu einer Anforderung.":"یک مثال واقعی برای یک شرط.","Eine allgemeine Eigenschaft ohne Tätigkeitsbezug.":"یک ویژگی کلی بدون ربط به کار.","Ein Nachweis, der nur ähnlich wie die geforderte Qualifikation heißt.":"مدرکی که فقط نامش شبیه صلاحیت خواسته‌شده است.","Ein konkretes Beispiel macht die behauptete Erfahrung nachvollziehbar.":"یک مثال مشخص تجربهٔ ادعاشده را قابل پیگیری می‌کند.","Was prüfst du vor dem Schreiben?":"پیش از نوشتن چه چیزی را بررسی می‌کنید؟","Nur die übliche Unterlagenliste aus einer früheren Bewerbung.":"فقط لست معمول اسناد از یک درخواست قبلی.","Nur das eigene Wunschdatum für ein Gespräch.":"فقط تاریخ دلخواه خودتان برای مصاحبه.","Geforderte Unterlagen und Bewerbungsweg.":"اسناد خواسته‌شده و راه درخواست.","Vorgaben bestimmen, was eingereicht und wie die Bewerbung zugeordnet werden soll.":"خواسته‌ها تعیین می‌کنند که چه چیزی فرستاده شود و درخواست چطور مربوط شود.","Schreibe zu jeder zentralen Anforderung eine echte Erfahrung oder kennzeichne die Lücke offen.":"برای هر شرط اصلی یک تجربهٔ واقعی بنویسید یا کمبود را آشکارا مشخص کنید.","Anforderungen mit Erfahrungen verbinden":"وصل کردن شرط‌ها با تجربه‌ها","Lina: „Die Anzeige nennt Kundenkontakt und Bestellbearbeitung.“ Berater: „Was hast du schon gemacht?“ Lina: „Im Laden habe ich Kunden beraten. Bestellungen habe ich nur unter Anleitung erfasst.“ Berater: „Dann beschreibst du genau das und behauptest keine eigenständige Verantwortung.“ Lina: „Für die Einarbeitung frage ich nach dem verwendeten System.“":"لینا: «اعلان تماس با مشتری و پردازش سفارش را نام می‌برد.» مشاور: «تا حالا چه کرده‌ای؟» لینا: «در دکان به مشتریان مشوره داده‌ام. سفارش‌ها را فقط تحت راهنمایی ثبت کرده‌ام.» مشاور: «پس دقیقاً همین را توصیف کن و مسئولیت مستقل را ادعا نکن.» لینا: «برای آموزش اولیه دربارهٔ سیستم مورد استفاده می‌پرسم.»","Eine Anforderungs-Beleg-Liste erstellen":"ساختن یک لست شرط و مدرک","Lege drei Spalten an: Anforderung, Erfahrung, möglicher Nachweis. Ein Beispiel aus dem Vereinsverkauf kann Kundenkontakt zeigen, muss aber als ehrenamtlich benannt bleiben. Nicht jede Erfahrung hat ein Zeugnis. Eine nachvollziehbare Tätigkeitsbeschreibung ist hilfreicher als ein erfundenes Zertifikat. Entscheide, welche Angaben für diese Stelle wirklich relevant sind.":"سه ستون بسازید: شرط، تجربه، مدرک احتمالی. یک مثال از فروش در انجمن می‌تواند تماس با مشتری را نشان دهد، اما باید داوطلبانه نامیده شود. هر تجربه‌ای تصدیق‌نامه ندارد. یک توضیح قابل پیگیری کار از یک گواهی‌نامهٔ ساختگی مفیدتر است. تصمیم بگیرید که کدام معلومات واقعاً برای این کار مهم است.","Unterlagen aus der Vorgabe ableiten":"بیرون کشیدن اسناد از خواسته‌ها","Ein Anschreiben erklärt, warum deine Erfahrung zur Stelle passt. Der Lebenslauf zeigt deinen bisherigen Weg. Lies zuerst, welche Unterlagen der Betrieb verlangt. Wird nur ein Lebenslauf gewünscht, schickst du nicht ungefragt eine große Mappe. Ist die Liste unklar? Frage über den offiziellen Kontakt nach, bevor du die Bewerbung vorbereitest.":"یک نامهٔ درخواست (Anschreiben) توضیح می‌دهد که چرا تجربهٔ شما با کار جور می‌آید. رزومه راه تا حالای شما را نشان می‌دهد. اول بخوانید که محل کار کدام اسناد را می‌خواهد. اگر فقط یک رزومه خواسته شده، بی‌پرسش یک پوشهٔ بزرگ نمی‌فرستید. لست نامشخص است؟ از راه تماس رسمی بپرسید، پیش از اینکه درخواست را آماده کنید.","Den Plan vor dem Schreiben prüfen":"بررسی برنامه پیش از نوشتن","Notiere Kennziffer, gewünschte Dokumente und Einreichungsweg. Danach entwirfst du die Inhalte. Ein allgemeiner Text ohne Bezug zur Tätigkeit erklärt kaum, warum die Stelle passt. Behalte die Anzeige für die spätere Gesprächsvorbereitung. Prüfe am Ende jede Behauptung in deinem Entwurf. Kannst du sie mit einer echten Tätigkeit oder einem vorhandenen Nachweis erklären?":"شمارهٔ اعلان، اسناد خواسته‌شده و راه فرستادن را یادداشت کنید. بعد از آن محتوا را طرح می‌کنید. یک متن کلی بدون ربط به کار به سختی توضیح می‌دهد که چرا کار جور است. اعلان را برای آمادگی مصاحبهٔ بعدی نگه دارید. در پایان هر ادعا در پیش‌نویس خود را بررسی کنید. آیا می‌توانید آن را با یک کار واقعی یا یک مدرک موجود توضیح دهید؟","Eine ehrliche Formulierung ergänzen":"کامل کردن یک جملهٔ صادقانه","Setze „Anleitung“ und „Kunden“ ein.":"„Anleitung“ (راهنمایی) و „Kunden“ (مشتریان) را بگذارید.","Die Aussagen dürfen die Verantwortung nicht vergrößern.":"جمله‌ها نباید مسئولیت را بزرگ‌تر نشان دهند.","Die Formulierungen entsprechen den tatsächlichen Tätigkeiten im Dialog.":"این جمله‌ها با کارهای واقعی در گفتگو جور می‌آیند.","Lina erfasste Bestellungen unter ___.":"Lina erfasste Bestellungen unter ___. (لینا سفارش‌ها را تحت ___ ثبت کرد.)","Im Laden beriet sie ___.":"Im Laden beriet sie ___. (در دکان به ___ مشوره داد.)","Unterlagen und Zwecke verbinden":"وصل کردن اسناد و هدف‌ها","Ordne die Funktionen zu.":"کارکردها را وصل کنید.","Die Dokumente ergänzen sich statt dieselbe Aufgabe zu übernehmen.":"اسناد همدیگر را کامل می‌کنند، به جای اینکه یک کار را انجام دهند.","Jeder Teil liefert eine andere Information für die Bewerbung.":"هر بخش معلومات دیگری برای درخواست می‌دهد.","Anschreiben":"نامهٔ درخواست","Lebenslauf":"رزومه","Nachweis":"مدرک","Die Erfahrung hören":"شنیدن تجربه","Unter welchen Bedingungen erfasste Lina Bestellungen? Antworte mit „unter“ und einem Nomen.":"لینا سفارش‌ها را در چه شرایطی ثبت کرد؟ با „unter“ و یک اسم جواب دهید.","Achte auf den Gegensatz zwischen beiden Tätigkeiten.":"به تضاد بین دو کار توجه کنید.","Nur die Bestellerfassung erfolgte unter Anleitung.":"فقط ثبت سفارش تحت راهنمایی انجام شد.","Einen Bewerbungsplan schreiben":"نوشتن یک برنامهٔ درخواست","Schreibe drei Sätze zu Anforderungen, Linas Belegen und einer offenen Frage.":"سه جمله دربارهٔ شرط‌ها، مدارک لینا و یک سوال باز بنویسید.","Übernimm die Tätigkeiten präzise statt sie aufzuwerten.":"کارها را دقیق بنویسید، به جای اینکه آن‌ها را بزرگ‌تر جلوه دهید.","Der Plan verbindet Anforderungen, ehrliche Belege und Informationsbedarf.":"این برنامه شرط‌ها، مدارک صادقانه و نیاز به معلومات را وصل می‌کند.","Nennst du beide Anforderungen?":"آیا هر دو شرط را نام می‌برید؟","Bleibt die Anleitung bei der Bestellerfassung sichtbar?":"آیا راهنمایی در ثبت سفارش دیده می‌ماند؟","Verwendest du ausschließlich tatsächliche Erfahrungen des Beispiels?":"آیا فقط تجربه‌های واقعی مثال را به کار می‌برید؟","Enthält der Plan eine passende Rückfrage?":"آیا برنامه یک سوال مناسب دارد؟","Ein passender Beleg beschreibt die tatsächlich ausgeführte Tätigkeit.":"یک مدرک مناسب کاری را توصیف می‌کند که واقعاً انجام شده است.","Die Anzeige bestimmt den Ausgangspunkt der Unterlagenauswahl.":"اعلان نقطهٔ شروع انتخاب اسناد را تعیین می‌کند.","Einen übersichtlichen Lebenslauf aufbauen":"ساختن یک رزومهٔ مرتب","Du beschreibst Stationen mit Zeitraum, Funktion und relevanten Tätigkeiten.":"شما بخش‌های رزومه را با مدت، نقش و کارهای مربوط توصیف می‌کنید.","Aufgaben zum Berufsabschluss umdeuten":"کارها را مدرک مسلکی جلوه دادن","Falsch: Omid als Meister ausweisen, weil er in einer Werkstatt half. Richtig: Funktion und angeleitete Tätigkeiten ohne erfundenen Abschluss beschreiben.":"اشتباه: امید را استادکار (Meister) نشان دهید، چون در یک ورکشاپ کمک کرده است. درست: نقش و کارهای تحت راهنمایی را بدون مدرک ساختگی توصیف کنید.","Zeiträume widersprüchlich notieren":"نوشتن متناقض مدت‌ها","Falsch: Dieselbe Station mit zwei unterschiedlichen Enddaten angeben. Richtig: Den belegten Zeitraum einheitlich übernehmen.":"اشتباه: یک بخش را با دو تاریخ پایان متفاوت بنویسید. درست: مدت ثابت‌شده را یکسان بنویسید.","Welche Station entspricht Omids Angaben?":"کدام بخش با معلومات امید جور می‌آید؟","Werkstatt, 03/2023–02/2025, selbstständige Leitung der Montage.":"ورکشاپ، 03/2023–02/2025، مدیریت مستقل نصب.","Werkstatt, 03/2023–02/2025, abgeschlossene Meisterausbildung.":"ورکشاپ، 03/2023–02/2025، آموزش کامل‌شدهٔ استادکاری.","Werkstatt, 03/2023–02/2025, Materialvorbereitung und angeleitete Montage.":"ورکشاپ، 03/2023–02/2025، آماده کردن مواد و نصب تحت راهنمایی.","Die Station übernimmt Zeitraum und tatsächliche Aufgaben ohne zusätzlichen Titel.":"این بخش مدت و کارهای واقعی را بدون عنوان اضافی می‌نویسد.","Was verbessert die Vergleichbarkeit der Stationen?":"چه چیزی مقایسهٔ بخش‌ها را بهتر می‌کند؟","Ein einheitliches Datums- und Gliederungsformat.":"یک قالب یکسان تاریخ و ساختار.","Die Stationen allein nach der Länge ihrer Beschreibung ordnen.":"مرتب کردن بخش‌ها فقط بر اساس طول توضیحشان.","Für jede Station ein anderes Datumsformat verwenden.":"به کار بردن قالب تاریخ متفاوت برای هر بخش.","Gleiche Strukturen lassen Zeiträume und Funktionen leichter erfassen.":"ساختارهای یکسان دیدن مدت‌ها و نقش‌ها را آسان‌تر می‌کنند.","Was prüfst du nach dem PDF-Export?":"بعد از صدور PDF چه چیزی را بررسی می‌کنید؟","Nur ob sich die Datei technisch öffnen lässt.":"فقط اینکه آیا فایل از نظر فنی باز می‌شود.","Lesbarkeit, Seitenumbrüche und vollständige Inhalte.":"خوانایی، شکستن صفحه‌ها و کامل بودن محتوا.","Nur ob der Dateiname die Stelle nennt.":"فقط اینکه آیا نام فایل کار را نام می‌برد.","Der Export kann trotz korrektem Entwurf Layoutfehler verursachen.":"صدور ممکن است با وجود یک پیش‌نویس درست خطای صفحه‌آرایی ایجاد کند.","Prüfe jeden Zeitraum auf Nachvollziehbarkeit und beschreibe eine Phase ohne Beschäftigung sachlich.":"هر مدت را از نظر قابل پیگیری بودن بررسی کنید و یک دورهٔ بدون کار را واقع‌بینانه توصیف کنید.","Eine Station präzisieren":"دقیق کردن یک بخش","Omid: „Ich war zwei Jahre in einer Werkstatt.“ Beraterin: „Wann genau und mit welchen Aufgaben?“ Omid: „Von März 2023 bis Februar 2025. Ich habe Material vorbereitet und einfache Montagearbeiten unter Anleitung gemacht.“ Beraterin: „Dann schreiben wir das so. Einen Meistertitel darfst du daraus nicht machen.“":"امید: «دو سال در یک ورکشاپ بودم.» مشاور: «دقیقاً چه وقت و با کدام کارها؟» امید: «از مارچ 2023 تا فبروری 2025. مواد را آماده کردم و کارهای سادهٔ نصب را تحت راهنمایی انجام دادم.» مشاور: «پس همین را می‌نویسیم. از این نمی‌توانی عنوان استادکار بسازی.»","Stationen einheitlich strukturieren":"ساختار یکسان بخش‌ها","Ein übersichtlicher Lebenslauf verwendet ein einheitliches Datumsformat und ordnet die neueste relevante Station üblicherweise zuerst. Zu jeder Station gehören Zeitraum, Betrieb oder Einrichtung und Funktion. Zwei bis drei konkrete Tätigkeiten reichen oft besser als lange Absätze. Wähle für alle Stationen dieselbe Struktur, damit sie vergleichbar bleiben.":"یک رزومهٔ مرتب یک قالب یکسان تاریخ به کار می‌برد و تازه‌ترین بخش مربوط را معمولاً اول می‌گذارد. هر بخش مدت، شرکت یا نهاد و نقش دارد. دو تا سه کار مشخص اغلب از پاراگراف‌های طولانی بهترند. برای همهٔ بخش‌ها یک ساختار انتخاب کنید تا قابل مقایسه بمانند.","Phasen offen und knapp benennen":"نام بردن آشکار و کوتاه دوره‌ها","Beschreibe auch Zeiten ohne Beschäftigung knapp und ehrlich. Hast du einen Sprachkurs besucht, nenne den Kurs und den Zeitraum. Eine Familienphase ist keine Beschäftigung in einem Betrieb. Erfinde deshalb keine Stelle, um eine Lücke zu verdecken. Private Einzelheiten brauchst du dafür nicht ausführlich zu erklären.":"وقت‌های بدون کار را هم کوتاه و صادقانه توصیف کنید. اگر در یک کورس زبان شرکت کرده‌اید، کورس و مدت را نام ببرید. یک دورهٔ خانوادگی کار در یک شرکت نیست. به همین دلیل هیچ کار ساختگی برای پوشاندن یک کمبود نسازید. لازم نیست جزئیات خصوصی را مفصل توضیح دهید.","Kontaktdaten und Ausgabe kontrollieren":"بررسی معلومات تماس و خروجی","Eine erreichbare E-Mail-Adresse und korrekte Telefonnummer ermöglichen Rückfragen. Prüfe die fertige Datei nach dem Export auf abgeschnittene Texte, verschobene Daten und lesbare Schrift. Ein schönes Layout ersetzt keine richtigen Zeiträume. Speichere den Entwurf unter einem klaren Dateinamen und unterscheide die versandte Fassung von späteren Änderungen.":"یک آدرس ایمیل قابل دسترس و یک شمارهٔ تیلفون درست پرسیدن را ممکن می‌کنند. فایل نهایی را بعد از صدور از نظر متن‌های بریده‌شده، تاریخ‌های جابه‌جاشده و فونت خوانا بررسی کنید. یک صفحه‌آرایی زیبا جای مدت‌های درست را نمی‌گیرد. پیش‌نویس را با یک نام فایل روشن ذخیره کنید و نسخهٔ فرستاده‌شده را از تغییرهای بعدی جدا کنید.","Die Station ergänzen":"کامل کردن بخش","Setze „2023“ und „2025“ ein.":"„2023“ و „2025“ را بگذارید.","Übernimm die Zeitangaben aus dem Gespräch.":"زمان‌ها را از گفتگو بنویسید.","Die Station reicht von März 2023 bis Februar 2025.":"این بخش از مارچ 2023 تا فبروری 2025 است.","Beginn der Werkstattstation: März ___.":"شروع بخش ورکشاپ: مارچ ___.","Ende der Werkstattstation: Februar ___.":"پایان بخش ورکشاپ: فبروری ___.","Lebenslaufangaben ordnen":"مرتب کردن معلومات رزومه","Verbinde die Angabe mit ihrer Rolle.":"معلومات را به نقش آن وصل کنید.","Eine Aufgabe ist kein Zeitraum und kein Abschluss.":"یک کار نه مدت است و نه مدرک.","Die Zuordnung verhindert eine Vermischung verschiedener Angaben.":"این وصل کردن از مخلوط شدن معلومات مختلف جلوگیری می‌کند.","Material vorbereiten":"آماده کردن مواد","Werkstatt":"ورکشاپ","Das Enddatum erfassen":"ثبت تاریخ پایان","In welchem Jahr endete Omids Werkstattstation? Schreibe vier Ziffern.":"بخش ورکشاپ امید در کدام سال تمام شد؟ چهار رقم بنویسید.","Gesucht ist das Ende, nicht der Beginn.":"پایان خواسته شده، نه شروع.","Die Station endete im Februar 2025.":"این بخش در فبروری 2025 تمام شد.","Eine Lebenslaufstation formulieren":"نوشتن یک بخش رزومه","Formuliere Omids Station in zwei bis drei Zeilen mit Zeitraum und Aufgaben.":"بخش امید را در دو تا سه خط با مدت و کارها بنویسید.","Nutze kurze Formulierungen und dieselbe Struktur wie bei anderen Stationen.":"جمله‌های کوتاه و همان ساختار بخش‌های دیگر را به کار ببرید.","Die Station bleibt übersichtlich und inhaltlich beim belegten Umfang.":"این بخش مرتب و از نظر محتوا در اندازهٔ ثابت‌شده می‌ماند.","Sind Beginn und Ende richtig angegeben?":"آیا شروع و پایان درست نوشته شده‌اند؟","Beschreibst du Materialvorbereitung und Montage konkret?":"آیا آماده کردن مواد و نصب را مشخص توصیف می‌کنید؟","Bleibt die Anleitung bei der Montage enthalten?":"آیا راهنمایی در نصب باقی می‌ماند؟","Verzichtest du auf einen erfundenen Berufsabschluss?":"آیا از یک مدرک مسلکی ساختگی پرهیز می‌کنید؟","Eine Station enthält nachvollziehbare Zeiten und passende Tätigkeiten.":"یک بخش مدت‌های قابل پیگیری و کارهای مناسب دارد.","Ein PDF-Export muss nach dem Erstellen noch visuell geprüft werden.":"یک صدور PDF بعد از ساختن هنوز باید با چشم بررسی شود.","Ein Anschreiben mit passenden Beispielen verfassen":"نوشتن یک نامهٔ درخواست با مثال‌های مناسب","Du begründest die Bewerbung anhand der Tätigkeit und beziehst Erfahrungen konkret darauf.":"شما درخواست را بر اساس کار توجیه می‌کنید و تجربه‌ها را مشخص به آن وصل می‌کنید.","Erfahrungen durch Floskeln ersetzen":"جایگزین کردن تجربه‌ها با جمله‌های کلیشه‌ای","Falsch: Nur „hoch motiviert und perfekt geeignet“ schreiben. Richtig: Die Motivation mit einer relevanten Aufgabe und einem konkreten Beispiel erklären.":"اشتباه: فقط بنویسید «بسیار باانگیزه و کاملاً مناسب». درست: انگیزه را با یک کار مربوط و یک مثال مشخص توضیح دهید.","Alten Firmennamen stehen lassen":"باقی گذاشتن نام شرکت قدیمی","Falsch: Im Text eine andere Firma ansprechen als im Betreff. Richtig: Empfänger, Firmenname und Stelle gemeinsam kontrollieren.":"اشتباه: در متن شرکت دیگری را خطاب کنید تا در موضوع. درست: گیرنده، نام شرکت و کار را با هم بررسی کنید.","Welches Beispiel stützt Noras Interesse an Kundenberatung?":"کدام مثال علاقهٔ نورا به مشورهٔ مشتری را تأیید می‌کند؟","Sie interessiert sich für das Getränkesortiment als Kundin.":"او به عنوان مشتری به نوشیدنی‌های فروشگاه علاقه دارد.","Sie hat im Vereinscafé Fragen beantwortet.":"او در کافهٔ انجمن به سوال‌ها جواب داده است.","Sie hat die Stellenanzeige mehrfach gelesen.":"او اعلان کار را چند بار خوانده است.","Das Beantworten von Fragen zeigt einen relevanten Bezug zu Beratung.":"جواب دادن به سوال‌ها ربط مربوطی به مشوره نشان می‌دهد.","Welcher Satz ist grammatisch korrekt?":"کدام جمله از نظر دستور زبان درست است؟","Der weil-Satz endet mit dem konjugierten „habe“.":"جملهٔ weil با فعل صرف‌شدهٔ „habe“ تمام می‌شود.","Was sollte das Anschreiben ergänzen?":"نامهٔ درخواست باید چه چیزی را اضافه کند؟","Motivation und ausgewählte passende Belege.":"انگیزه و مدارک مناسب انتخاب‌شده.","Den gesamten Lebenslauf noch einmal in ganzen Sätzen.":"تمام رزومه را یک بار دیگر در جمله‌های کامل.","Nur eine allgemeine Liste positiver Eigenschaften.":"فقط یک لست کلی از ویژگی‌های مثبت.","Das Anschreiben erklärt den Bezug zur Stelle, statt den Lebenslauf vollständig zu wiederholen.":"نامهٔ درخواست ربط با کار را توضیح می‌دهد، به جای اینکه رزومه را کامل تکرار کند.","Ersetze eine leere Eigenschaft wie „teamfähig“ durch ein kurzes Beispiel aus einer wirklichen Zusammenarbeit.":"یک ویژگی خالی مثل „teamfähig“ (اهل کار گروهی) را با یک مثال کوتاه از یک همکاری واقعی عوض کنید.","Die Motivation konkretisieren":"مشخص کردن انگیزه","Nora: „Ich schreibe: Hiermit bewerbe ich mich, weil Ihre Firma toll ist.“ Coach: „Was interessiert dich an der Aufgabe?“ Nora: „Die Kundenberatung. Im Vereinscafé habe ich Fragen beantwortet und Bestellungen aufgenommen.“ Coach: „Dann verbindest du genau diese Erfahrung mit der ausgeschriebenen Tätigkeit.“":"نورا: «می‌نویسم: Hiermit bewerbe ich mich, weil Ihre Firma toll ist (درخواست می‌دهم، چون شرکت شما عالی است).» مربی: «چه چیزی در این کار برایت جالب است؟» نورا: «مشورهٔ مشتری. در کافهٔ انجمن به سوال‌ها جواب دادم و سفارش گرفتم.» مربی: «پس دقیقاً همین تجربه را با کار اعلان‌شده وصل کن.»","Bezug statt allgemeinem Lob herstellen":"ساختن ربط به جای تعریف کلی","Nenne die Stelle und gegebenenfalls ihre Kennziffer. Erkläre danach, welche Aufgabe dich anspricht und warum eine Erfahrung dazu passt. „Ich bin zuverlässig“ gewinnt an Aussagekraft durch ein zutreffendes Beispiel. Wiederhole nicht den ganzen Lebenslauf. Ein Anschreiben ergänzt die geordneten Stationen um Motivation und ausgewählte Belege.":"کار و در صورت لزوم شمارهٔ اعلان آن را نام ببرید. بعد توضیح دهید که کدام کار شما را جذب می‌کند و چرا یک تجربه با آن جور است. «من قابل اعتمادم» با یک مثال درست گویاتر می‌شود. تمام رزومه را تکرار نکنید. یک نامهٔ درخواست بخش‌های مرتب رزومه را با انگیزه و مدارک انتخاب‌شده کامل می‌کند.","Angemessen und korrekt formulieren":"نوشتن مناسب و درست","Erkläre dein Interesse an einer konkreten Aufgabe. Du kannst schreiben: „Die Kundenberatung interessiert mich, weil ich gern verständlich auf Fragen eingehe.“ Nach „weil“ steht das Verb hinten. Kennst du den richtigen Namen der Kontaktperson, nutze ihn in der Anrede. Sonst wählst du eine allgemeine Anrede, statt einen Namen zu raten.":"علاقهٔ خود به یک کار مشخص را توضیح دهید. می‌توانید بنویسید: „Die Kundenberatung interessiert mich, weil ich gern verständlich auf Fragen eingehe.“ (مشورهٔ مشتری برایم جالب است، چون دوست دارم به سوال‌ها قابل فهم جواب بدهم.) بعد از „weil“ فعل در آخر می‌آید. اگر نام درست شخص تماس را می‌دانید، آن را در خطاب به کار ببرید. در غیر آن یک خطاب عمومی انتخاب کنید، به جای اینکه یک نام را حدس بزنید.","Vor dem Versand den Bezug kontrollieren":"بررسی ربط پیش از فرستادن","Lies Firmenname, Stellenbezeichnung und Empfänger besonders sorgfältig. Ein alter Firmenname im Entwurf verrät einen ungeprüften Austausch. Prüfe außerdem, ob jede genannte Erfahrung stimmt und ob der Text die Anforderungen der konkreten Stelle trifft. Eine Bitte um ein Gespräch ist passend, eine Zusage des Betriebs darfst du daraus nicht ableiten.":"نام شرکت، عنوان کار و گیرنده را به‌خصوص با دقت بخوانید. یک نام قدیمی شرکت در پیش‌نویس یک تعویض بررسی‌نشده را نشان می‌دهد. همچنین بررسی کنید که آیا هر تجربهٔ نام‌برده درست است و آیا متن شرط‌های کار مشخص را برآورده می‌کند. یک درخواست مصاحبه مناسب است، اما نمی‌توانید از آن قبولی شرکت را نتیجه بگیرید.","Eine Begründung abschließen":"تمام کردن یک دلیل","Setze „habe“ und „interessiert“ ein.":"„habe“ و „interessiert“ را بگذارید.","Im Nebensatz steht das Verb hinten, im Hauptsatz an zweiter Stelle.":"در جملهٔ فرعی فعل در آخر و در جملهٔ اصلی در جای دوم است.","Die Formen passen zu Erfahrung und Interesse an der Aufgabe.":"این شکل‌ها با تجربه و علاقه به کار جور می‌آیند.","Die Beratung passt zu mir, weil ich darin Erfahrung ___.":"Die Beratung passt zu mir, weil ich darin Erfahrung ___. (مشوره با من جور است، چون در آن تجربه ___.)","Die Kundenberatung ___ mich besonders.":"Die Kundenberatung ___ mich besonders. (مشورهٔ مشتری مرا به‌خصوص ___.)","Textabsichten zuordnen":"وصل کردن هدف‌های متن","Ordne die Aussage ihrem Zweck zu.":"گفته را به هدف آن وصل کنید.","Der Text erklärt Ziel, Grund und passenden Hintergrund.":"متن هدف، دلیل و سابقهٔ مناسب را توضیح می‌دهد.","Die drei Funktionen ergeben ein nachvollziehbares Anschreiben.":"این سه کارکرد یک نامهٔ درخواست قابل فهم می‌سازند.","Ich bewerbe mich als Servicekraft.":"من برای کار خدمات درخواست می‌دهم.","Beratung interessiert mich.":"مشوره برایم جالب است.","Ich beantwortete Kundenfragen.":"من به سوال‌های مشتریان جواب دادم.","Die passende Erfahrung hören":"شنیدن تجربهٔ مناسب","Wo hat Nora Fragen beantwortet? Antworte mit einem Nomen.":"نورا کجا به سوال‌ها جواب داده است؟ با یک اسم (به آلمانی) جواب دهید.","Die Frage betrifft den direkten Kontakt mit Gästen.":"سوال به تماس مستقیم با مهمانان مربوط است.","Noras Beratungsbeispiel stammt aus dem Vereinscafé.":"مثال مشورهٔ نورا از کافهٔ انجمن (Vereinscafé) است.","Einen Anschreibenabsatz verfassen":"نوشتن یک پاراگراف نامهٔ درخواست","Schreibe einen Absatz mit Stelle, Motivation und Noras zutreffendem Beispiel.":"یک پاراگراف با کار، انگیزه و مثال درست نورا بنویسید.","Verknüpfe eine Erfahrung mit einer Aufgabe, statt viele Eigenschaften aufzuzählen.":"یک تجربه را با یک کار وصل کنید، به جای اینکه ویژگی‌های زیادی بشمارید.","Der Absatz erklärt die Passung ohne erfundene Fachkenntnisse.":"این پاراگراف جور بودن را بدون دانش تخصصی ساختگی توضیح می‌دهد.","Ist die Stelle eindeutig benannt?":"آیا کار روشن نام برده شده است؟","Erklärst du das Interesse an der konkreten Tätigkeit?":"آیا علاقه به کار مشخص را توضیح می‌دهید؟","Nennst du das zutreffende Beispiel aus dem Vereinscafé?":"آیا مثال درست از کافهٔ انجمن را نام می‌برید؟","Steht das Verb im weil-Satz an der passenden Stelle?":"آیا فعل در جملهٔ weil در جای مناسب است؟","Ein Anschreiben verbindet Aufgabe, Motivation und ein passendes Beispiel.":"یک نامهٔ درخواست کار، انگیزه و یک مثال مناسب را وصل می‌کند.","Der konkrete Stellenbezug wird für jede Bewerbung erneut geprüft.":"ربط مشخص با کار برای هر درخواست دوباره بررسی می‌شود.","Bewerbungsunterlagen für das Gespräch nutzen":"استفاده از اسناد درخواست برای مصاحبه","Du bereitest dich mit den tatsächlich versandten Angaben auf Nachfragen vor.":"شما با معلوماتی که واقعاً فرستاده‌اید برای پرسش‌های بعدی آماده می‌شوید.","Fremde Verantwortung übernehmen":"پذیرفتن مسئولیت دیگران","Falsch: Nora behauptet die Abrechnung, obwohl sie nur Bestellungen notierte. Richtig: Die eigene Aufgabe nennen und die fremde Aufgabe klar abgrenzen.":"اشتباه: نورا حساب‌داری را ادعا می‌کند، با اینکه فقط سفارش‌ها را یادداشت کرده است. درست: کار خودتان را نام ببرید و کار دیگری را روشن جدا کنید.","Mit einer anderen Fassung üben":"تمرین با نسخهٔ دیگر","Falsch: Nur einen unversandten Entwurf lesen und die abgegebenen Angaben vergessen. Richtig: Die tatsächlich versandte Fassung zur Vorbereitung nutzen.":"اشتباه: فقط یک پیش‌نویس فرستاده‌نشده را بخوانید و معلومات فرستاده‌شده را فراموش کنید. درست: نسخهٔ واقعاً فرستاده‌شده را برای آمادگی به کار ببرید.","Welche Aufgabe hat Nora tatsächlich ausgeführt?":"نورا واقعاً کدام کار را انجام داده است؟","Getränke kassiert und die Tagesabrechnung geführt.":"پول نوشیدنی‌ها را گرفته و حساب روزانه را نگه داشته است.","Den Einkauf und die Preise des Cafés festgelegt.":"خرید و قیمت‌های کافه را تعیین کرده است.","Getränkewünsche notiert und weitergegeben.":"خواسته‌های نوشیدنی را یادداشت کرده و رسانده است.","Nora beschreibt die Bestellaufnahme und grenzt die Abrechnung ausdrücklich ab.":"نورا گرفتن سفارش را توصیف می‌کند و حساب‌داری را صریحاً جدا می‌کند.","Welche eigene Frage passt zur Stelle?":"کدام سوال خودتان با کار جور می‌آید؟","Wie ist die Einarbeitung organisiert?":"آموزش اولیه چطور سازمان‌دهی شده است؟","Wann beginnt meine bereits zugesagte Einarbeitung?":"آموزش اولیهٔ از قبل قبول‌شدهٔ من چه وقت شروع می‌شود؟","Welche Schulung habe ich laut Ihrer Zusage schon bestanden?":"بر اساس قبولی شما کدام آموزش را از قبل گذرانده‌ام؟","Die Einarbeitung ist eine sachliche Frage zum Arbeitsalltag ohne angenommene Zusage.":"آموزش اولیه یک سوال واقعی دربارهٔ کار روزمره است، بدون فرض قبولی.","Welche Fassung solltest du vorher lesen?":"پیش از آن کدام نسخه را باید بخوانید؟","Den zuletzt überarbeiteten, noch nicht versandten Entwurf.":"آخرین پیش‌نویس ویرایش‌شده که هنوز فرستاده نشده.","Die tatsächlich versandten Unterlagen.":"اسناد واقعاً فرستاده‌شده.","Eine allgemeine Vorlage ohne die Angaben zur Stelle.":"یک قالب عمومی بدون معلومات کار.","Die Gesprächspartner können sich auf genau die eingereichte Fassung beziehen.":"طرف‌های مصاحبه ممکن است دقیقاً به نسخهٔ فرستاده‌شده اشاره کنند.","Lies vor dem Gespräch deine versandte Fassung und suche zu zwei Aussagen je ein Beispiel.":"پیش از مصاحبه نسخهٔ فرستاده‌شدهٔ خود را بخوانید و برای دو گفته هر کدام یک مثال پیدا کنید.","Auf eine Rückfrage vorbereiten":"آمادگی برای یک سوال بعدی","Personalmitarbeiterin: „Sie schreiben, dass Sie Bestellungen aufgenommen haben. Wie lief das ab?“ Nora: „Im Vereinscafé notierte ich Getränkewünsche und gab sie an die Ausgabe weiter.“ Mitarbeiterin: „Haben Sie auch abgerechnet?“ Nora: „Nein, die Abrechnung hat eine andere Person übernommen.“ Eine präzise Antwort grenzt die eigene Verantwortung ehrlich ein.":"کارمند بخش کارکنان: «نوشته‌اید که سفارش گرفته‌اید. چطور بود؟» نورا: «در کافهٔ انجمن خواسته‌های نوشیدنی را یادداشت کردم و به بخش تحویل دادم.» کارمند: «حساب‌داری هم کرده‌اید؟» نورا: «نه، حساب‌داری را شخص دیگری انجام داد.» یک جواب دقیق مسئولیت خودتان را صادقانه محدود می‌کند.","Unterlagen und Beispiele verbinden":"وصل کردن اسناد و مثال‌ها","Markiere wichtige Aussagen im Lebenslauf und Anschreiben. Überlege, was die Tätigkeit konkret umfasste und was nicht. Eine kurze Beschreibung von Situation, Handlung und Ergebnis hilft bei Rückfragen. Bleibe bei Tatsachen, die du vertreten kannst. Ein geübtes Beispiel darf sprachlich klarer werden, aber nicht bei jeder Wiederholung zusätzliche Verantwortung erfinden.":"گفته‌های مهم را در رزومه و نامهٔ درخواست علامت بزنید. فکر کنید که کار مشخصاً چه چیزهایی را در بر داشت و چه چیزهایی را نه. یک توضیح کوتاه از وضعیت، کار و نتیجه در پرسش‌ها کمک می‌کند. به واقعیت‌هایی بسنده کنید که می‌توانید از آن‌ها دفاع کنید. یک مثال تمرین‌شده می‌تواند از نظر زبانی روشن‌تر شود، اما نباید با هر تکرار مسئولیت تازه‌ای بسازد.","Eigene Fragen aus der Anzeige ableiten":"بیرون کشیدن سوال‌های خودتان از اعلان","Leite eigene Fragen aus der Anzeige ab. Steht dort keine genaue Stundenverteilung, frage nach den Wochentagen und Zeiten. Du kannst auch fragen: „Wie ist die Einarbeitung organisiert?“ Damit möchtest du den Ablauf kennenlernen. Du behauptest noch nicht, dass der Betrieb dich eingestellt hat. Notiere die Antwort möglichst genau.":"سوال‌های خود را از اعلان بیرون بکشید. اگر آنجا تقسیم دقیق ساعت‌ها نیست، دربارهٔ روزها و وقت‌های هفته بپرسید. می‌توانید بپرسید: „Wie ist die Einarbeitung organisiert?“ (آموزش اولیه چطور سازمان‌دهی شده است؟) با این کار می‌خواهید روند را بشناسید. هنوز ادعا نمی‌کنید که شرکت شما را استخدام کرده است. جواب را تا حد ممکن دقیق یادداشت کنید.","Die passende Fassung bereitlegen":"آماده گذاشتن نسخهٔ مناسب","Speichere die tatsächlich versandten Dokumente mit Datum und Stelle. Sonst bereitest du dich womöglich auf einen später veränderten Entwurf vor. Notiere zwei sachliche Rückfragen und prüfe Einladung, Ort und Uhrzeit. Nutze hier deine Unterlagen, um Antworten auf Nachfragen zu üben. Der nächste Kurs behandelt das Gespräch und die ersten Arbeitstage genauer.":"اسناد واقعاً فرستاده‌شده را با تاریخ و کار ذخیره کنید. در غیر آن شاید برای یک پیش‌نویس که بعداً تغییر کرده آماده شوید. دو سوال واقعی یادداشت کنید و دعوت، جا و ساعت را بررسی کنید. اینجا از اسناد خود برای تمرین جواب‌ها به پرسش‌ها استفاده کنید. کورس بعدی مصاحبه و روزهای اول کار را دقیق‌تر بررسی می‌کند.","Verantwortung ergänzen":"کامل کردن مسئولیت","Setze „notierte“ und „andere“ ein.":"„notierte“ و „andere“ را بگذارید.","Unterscheide Noras eigene Handlung von der Aufgabe im Team.":"کار خود نورا را از کار گروه جدا کنید.","Die Angaben dürfen in der Vorbereitung nicht vertauscht werden.":"این معلومات نباید در آمادگی جابه‌جا شوند.","Nora ___ die Getränkewünsche.":"Nora ___ die Getränkewünsche. (نورا خواسته‌های نوشیدنی را ___.)","Die Abrechnung übernahm eine ___ Person.":"Die Abrechnung übernahm eine ___ Person. (حساب‌داری را یک شخص ___ انجام داد.)","Vorbereitungsschritte zuordnen":"وصل کردن قدم‌های آمادگی","Verbinde den Schritt mit seinem Zweck.":"قدم را به هدف آن وصل کنید.","Inhaltliche und organisatorische Vorbereitung ergänzen sich.":"آمادگی محتوایی و سازمانی همدیگر را کامل می‌کنند.","Die Schritte verhindern unterschiedliche Arten von Missverständnissen.":"این قدم‌ها از نوع‌های مختلف سوءتفاهم جلوگیری می‌کنند.","versandte Fassung lesen":"خواندن نسخهٔ فرستاده‌شده","ein Beispiel notieren":"یادداشت یک مثال","Einladung prüfen":"بررسی دعوت‌نامه","Die fremde Aufgabe heraushören":"شنیدن کار دیگری","Welche Aufgabe hat eine andere Person übernommen?":"کدام کار را شخص دیگری انجام داده است؟","Gesucht ist die ausdrücklich abgegrenzte Verantwortung.":"مسئولیتی خواسته شده که صریحاً جدا شده است.","Nora war im Beispiel nicht für die Abrechnung zuständig.":"نورا در مثال مسئول حساب‌داری (Abrechnung) نبود.","Eine Gesprächsvorbereitung notieren":"یادداشت یک آمادگی مصاحبه","Schreibe drei Sätze mit Noras eigener Aufgabe, der abgegrenzten Verantwortung und einer Frage zur Einarbeitung.":"سه جمله با کار خود نورا، مسئولیت جداشده و یک سوال دربارهٔ آموزش اولیه بنویسید.","Übe eine klare Abgrenzung, ohne die eigene Erfahrung abzuwerten.":"یک جداسازی روشن را تمرین کنید، بدون اینکه تجربهٔ خود را کم‌ارزش کنید.","Die Notiz hilft, bei Nachfragen präzise und ehrlich zu antworten.":"این یادداشت کمک می‌کند در پرسش‌ها دقیق و صادقانه جواب دهید.","Beschreibst du Noras Aufgabe konkret?":"آیا کار نورا را مشخص توصیف می‌کنید؟","Grenzt du die Abrechnung ausdrücklich ab?":"آیا حساب‌داری را صریحاً جدا می‌کنید؟","Bezieht sich die eigene Frage auf die Einarbeitung?":"آیا سوال خودتان به آموزش اولیه مربوط است؟","Bleiben deine Aussagen mit der Bewerbung vereinbar?":"آیا گفته‌های شما با درخواست جور می‌مانند؟","Eine Rückfrage kann jede Aussage der Bewerbung genauer prüfen.":"یک پرسش می‌تواند هر گفتهٔ درخواست را دقیق‌تر بررسی کند.","Die versandte Fassung ist die Grundlage der Gesprächsvorbereitung.":"نسخهٔ فرستاده‌شده پایهٔ آمادگی مصاحبه است.","Nachweise auswählen und verständlich ordnen":"انتخاب و مرتب کردن قابل فهم مدارک","Du stellst relevante Zeugnisse und Zertifikate entsprechend der Ausschreibung zusammen.":"شما تصدیق‌نامه‌ها و گواهی‌نامه‌های مربوط را بر اساس اعلان جمع می‌کنید.","Teilnahme als Abschluss ausweisen":"شرکت را مدرک فراغت جلوه دادن","Falsch: Eine Teilnahmebestätigung als bestandene Abschlussprüfung bezeichnen. Richtig: Den tatsächlichen Nachweis und seine Aussage genau benennen.":"اشتباه: یک تأیید شرکت را امتحان نهایی گذرانده‌شده بنامید. درست: مدرک واقعی و گفتهٔ آن را دقیق نام ببرید.","Unlesbaren Scan ungeprüft versenden":"فرستادن بدون بررسی یک اسکن ناخوانا","Falsch: Abgeschnittene Seiten als vollständigen Nachweis hochladen. Richtig: Jede Seite öffnen und bei Bedarf neu scannen.":"اشتباه: صفحه‌های بریده‌شده را به عنوان مدرک کامل بارگذاری کنید. درست: هر صفحه را باز کنید و در صورت نیاز دوباره اسکن کنید.","Welche Anlage passt zur ausdrücklich geforderten Qualifikation?":"کدام ضمیمه با صلاحیت صریحاً خواسته‌شده جور می‌آید؟","Der Bibliotheksausweis als allgemeiner Identitätsbeleg.":"کارت کتابخانه به عنوان مدرک عمومی هویت.","Das passende Kurszertifikat.":"گواهی‌نامهٔ کورس مناسب.","Eine Teilnahmebestätigung eines anderen, nicht verlangten Kurses.":"تأیید شرکت در یک کورس دیگر که خواسته نشده.","Das Zertifikat bezieht sich auf den in der Anzeige verlangten Kurs.":"گواهی‌نامه به کورسی مربوط است که در اعلان خواسته شده است.","Was muss nach dem Scannen geprüft werden?":"بعد از اسکن چه چیزی باید بررسی شود؟","Nur ob ein Upload ohne Fehlermeldung gelingt.":"فقط اینکه آیا بارگذاری بدون پیام خطا موفق است.","Nur ob die Datei einen passenden Namen hat.":"فقط اینکه آیا فایل نام مناسبی دارد.","Lesbarkeit und Vollständigkeit aller Seiten.":"خوانایی و کامل بودن همهٔ صفحه‌ها.","Eine vorhandene Datei kann trotzdem abgeschnittene oder fehlende Inhalte enthalten.":"یک فایل موجود ممکن است با این حال محتوای بریده یا کم داشته باشد.","Was bestätigt eine bloße Teilnahmebestätigung?":"یک تأیید شرکت ساده چه چیزی را تأیید می‌کند؟","Die Teilnahme im beschriebenen Umfang.":"شرکت در اندازهٔ توصیف‌شده.","Eine bestandene Abschlussprüfung ohne weitere Angabe.":"یک امتحان نهایی گذرانده‌شده بدون معلومات بیشتر.","Die Gleichwertigkeit mit dem verlangten Berufsabschluss.":"برابری با مدرک مسلکی خواسته‌شده.","Eine Teilnahmebestätigung darf nicht zu einem anderen Qualifikationsnachweis umgedeutet werden.":"یک تأیید شرکت نباید به مدرک صلاحیت دیگری تفسیر شود.","Wähle jeden Nachweis nach seiner Relevanz für die Stelle und kontrolliere, ob alle Seiten lesbar sind.":"هر مدرک را بر اساس مربوط بودنش به کار انتخاب کنید و بررسی کنید که آیا همهٔ صفحه‌ها خوانا هستند.","Eine Anlagenauswahl besprechen":"صحبت دربارهٔ انتخاب ضمیمه‌ها","Dina: „Soll ich alle meine Dokumente schicken?“ Berater: „Was verlangt die Anzeige?“ Dina: „Lebenslauf und das Zertifikat für den geforderten Kurs.“ Berater: „Dann prüfst du diese beiden Unterlagen zuerst.“ Dina: „Mein alter Bibliotheksausweis belegt die Qualifikation nicht.“ Berater: „Genau. Mehr Dokumente bedeuten nicht automatisch bessere Belege.“":"دینا: «آیا همهٔ اسنادم را بفرستم؟» مشاور: «اعلان چه می‌خواهد؟» دینا: «رزومه و گواهی‌نامهٔ کورس خواسته‌شده.» مشاور: «پس اول این دو سند را بررسی کن.» دینا: «کارت قدیمی کتابخانه‌ام صلاحیت را ثابت نمی‌کند.» مشاور: «دقیقاً. اسناد بیشتر خودکار به معنای مدارک بهتر نیست.»","Relevanz statt bloßer Menge prüfen":"بررسی مربوط بودن به جای تعداد","Ein Nachweis soll eine genannte Qualifikation oder Erfahrung verständlich belegen. Ordne ihn der passenden Aussage zu. Kontrolliere Name, Bezeichnung und Vollständigkeit. Ein Zertifikat über Teilnahme ist nicht automatisch der Nachweis einer bestandenen Abschlussprüfung. Gib den tatsächlichen Dokumenttyp wieder und verwende keine eigene amtlich klingende Aufwertung.":"یک مدرک باید یک صلاحیت یا تجربهٔ نام‌برده را قابل فهم ثابت کند. آن را به گفتهٔ مناسب وصل کنید. نام، عنوان و کامل بودن را بررسی کنید. یک گواهی شرکت خودکار مدرک یک امتحان نهایی گذرانده‌شده نیست. نوع واقعی سند را بگویید و هیچ بزرگ‌نمایی رسمی‌نمای خودتان را به کار نبرید.","Dateien sinnvoll benennen":"نام‌گذاری معقول فایل‌ها","Benenne Dateien so, dass der Inhalt erkennbar ist, etwa „Zertifikat_Kursname.pdf“. Ein Zeugnis und eine Kursbescheinigung können Unterschiedliches belegen. Prüfe den Text jedes Nachweises. Im Portal stehen meist Dateiformat und Größenlimit. Lies auch, ob du Dokumente einzeln oder als gemeinsame Datei hochladen sollst.":"فایل‌ها را طوری نام‌گذاری کنید که محتوا شناخته شود، مثلاً „Zertifikat_Kursname.pdf“. یک تصدیق‌نامه و یک گواهی کورس ممکن است چیزهای مختلفی را ثابت کنند. متن هر مدرک را بررسی کنید. در پورتال معمولاً قالب فایل و حد اندازه نوشته شده است. همچنین بخوانید که آیا باید اسناد را جداگانه یا به شکل یک فایل مشترک بارگذاری کنید.","Lesbarkeit und Datenschutz kontrollieren":"بررسی خوانایی و حفاظت داده","Öffne jede Datei nach dem Scannen und überprüfe Ausrichtung, abgeschnittene Ränder und fehlende Seiten. Entferne keine inhaltlichen Informationen, um eine Qualifikation besser erscheinen zu lassen. Sende keine zusätzlichen Ausweisdaten ohne geprüften Bedarf. Bewahre Originale sicher auf und reiche in dieser Übung ausschließlich erfundene Unterlagen als Lernbeispiele ein.":"هر فایل را بعد از اسکن باز کنید و جهت، حاشیه‌های بریده و صفحه‌های کم را بررسی کنید. هیچ معلومات محتوایی را برای بهتر نشان دادن یک صلاحیت برندارید. بدون نیاز بررسی‌شده معلومات اضافی تذکره نفرستید. اصل‌ها را محفوظ نگه دارید و در این تمرین فقط اسناد ساختگی را به عنوان مثال آموزشی بفرستید.","Dokumentbegriffe ergänzen":"کامل کردن کلمه‌های سند","Setze „Zertifikat“ und „Anlagen“ ein.":"„Zertifikat“ (گواهی‌نامه) و „Anlagen“ (ضمیمه‌ها) را بگذارید.","Suche die passende Dokumentart und den Sammelbegriff.":"نوع سند مناسب و کلمهٔ جمعی را پیدا کنید.","Ein einzelner Nachweis kann Teil der Anlagen einer Bewerbung sein.":"یک مدرک تنها می‌تواند بخشی از ضمیمه‌های یک درخواست باشد.","Der Kurs wird durch ein ___ belegt.":"Der Kurs wird durch ein ___ belegt. (کورس با یک ___ ثابت می‌شود.)","Beigefügte Dokumente heißen auch ___.":"Beigefügte Dokumente heißen auch ___. (اسناد ضمیمه‌شده ___ هم نامیده می‌شوند.)","Dateiprüfungen zuordnen":"وصل کردن بررسی‌های فایل","Verbinde das Problem mit der Prüfung.":"مشکل را به بررسی وصل کنید.","Prüfe Inhalt, Darstellung und technische Vorgabe getrennt.":"محتوا، نمایش و شرط فنی را جدا بررسی کنید.","Jede Kontrolle erkennt einen anderen möglichen Fehler.":"هر بررسی یک خطای احتمالی دیگر را می‌شناسد.","Text am Rand fehlt":"متن در حاشیه کم است","Schrift ist verschwommen":"نوشته تار است","Portal verlangt PDF":"پورتال PDF می‌خواهد","Die geforderte Anlage hören":"شنیدن ضمیمهٔ خواسته‌شده","Welcher Nachweis wird zusätzlich zum Lebenslauf verlangt? Antworte mit einem Nomen.":"علاوه بر رزومه کدام مدرک خواسته می‌شود؟ با یک اسم (به آلمانی) جواب دهید.","Gesucht ist die zusätzliche geforderte Anlage.":"ضمیمهٔ اضافی خواسته‌شده پرسیده شده است.","Das Kurszertifikat belegt die ausdrücklich genannte Qualifikation.":"گواهی‌نامهٔ کورس صلاحیت صریحاً نام‌برده را ثابت می‌کند.","Eine Anlagenauswahl begründen":"توجیه انتخاب ضمیمه‌ها","Schreibe drei Sätze zu Dinas Auswahl und der Qualitätsprüfung der Dateien.":"سه جمله دربارهٔ انتخاب دینا و بررسی کیفیت فایل‌ها بنویسید.","Wähle gezielt statt möglichst viele Dateien zu sammeln.":"هدفمند انتخاب کنید، به جای اینکه تا حد ممکن فایل زیاد جمع کنید.","Die Auswahl folgt der Ausschreibung und einer nachvollziehbaren Dateiprüfung.":"این انتخاب از اعلان و یک بررسی قابل پیگیری فایل پیروی می‌کند.","Sind die zwei verlangten Dokumente genannt?":"آیا دو سند خواسته‌شده نام برده شده‌اند؟","Begründest du den Verzicht auf den unpassenden Ausweis?":"آیا صرف‌نظر از کارت نامناسب را توجیه می‌کنید؟","Prüfst du Lesbarkeit und alle Seiten?":"آیا خوانایی و همهٔ صفحه‌ها را بررسی می‌کنید؟","Berücksichtigst du die technischen Portalvorgaben?":"آیا شرط‌های فنی پورتال را در نظر می‌گیرید؟","Ein Nachweis belegt nur das, was tatsächlich darin bestätigt wird.":"یک مدرک فقط چیزی را ثابت می‌کند که واقعاً در آن تأیید شده است.","Die Vorgabe entscheidet über getrennte oder gemeinsame Dateien.":"خواستهٔ اعلان دربارهٔ فایل‌های جدا یا مشترک تصمیم می‌گیرد.","Eine Online-Bewerbung sorgfältig einreichen":"فرستادن دقیق یک درخواست آنلاین","Du prüfst Formularfelder und Dateien und unterscheidest Entwurf, Versand und Eingang.":"شما خانه‌های فورم و فایل‌ها را بررسی می‌کنید و پیش‌نویس، فرستادن و دریافت را جدا می‌کنید.","Upload mit Versand gleichsetzen":"یکی دانستن بارگذاری با فرستادن","Falsch: „Die Dateien sind hochgeladen, also ist die Bewerbung versandt.“ Richtig: Versandaktion und Bestätigung beziehungsweise Portalstatus prüfen.":"اشتباه: «فایل‌ها بارگذاری شده‌اند، پس درخواست فرستاده شده است.» درست: کار فرستادن و تأیید یا وضعیت پورتال را بررسی کنید.","Automatisch erkannte Daten blind übernehmen":"پذیرفتن کورکورانهٔ داده‌های خودکار تشخیص‌داده‌شده","Falsch: Einen falsch erkannten Zeitraum ungeprüft lassen. Richtig: Formular und Lebenslauf vor dem Absenden abgleichen.":"اشتباه: یک مدت اشتباه تشخیص‌داده‌شده را بدون بررسی باقی بگذارید. درست: فورم و رزومه را پیش از فرستادن مقایسه کنید.","Was bedeutet der Status Entwurf?":"وضعیت Entwurf (پیش‌نویس) یعنی چه؟","Die Bewerbung ist abgeschickt, aber noch ungelesen.":"درخواست فرستاده شده، اما هنوز خوانده نشده.","Die Bewerbung ist noch nicht fertig eingereicht.":"درخواست هنوز کامل فرستاده نشده است.","Die Unterlagen sind bereits inhaltlich geprüft.":"اسناد از قبل از نظر محتوا بررسی شده‌اند.","Ein gespeicherter Entwurf ist noch kein abgeschlossener Versand.":"یک پیش‌نویس ذخیره‌شده هنوز یک فرستادن تمام‌شده نیست.","Was wird vor dem Absenden verglichen?":"پیش از فرستادن چه چیزی مقایسه می‌شود؟","Formularangaben und zugehörige Unterlagen.":"معلومات فورم و اسناد مربوط.","Nur die Angaben im automatisch ausgefüllten Formular.":"فقط معلومات فورم خودکار پرشده.","Nur die hochgeladenen PDF-Dateien.":"فقط فایل‌های PDF بارگذاری‌شده.","Doppelt angegebene Daten müssen konsistent sein und Erkennungsfehler korrigiert werden.":"داده‌هایی که دو بار نوشته شده‌اند باید یکسان باشند و خطاهای تشخیص اصلاح شوند.","Was bestätigt eine Eingangsbestätigung?":"یک تأیید دریافت چه چیزی را تأیید می‌کند؟","Die Unterlagen sind vollständig und fachlich geprüft.":"اسناد کامل و از نظر تخصصی بررسی شده‌اند.","Den Eingang der Bewerbung.":"دریافت درخواست را.","Die Person wurde für ein Gespräch ausgewählt.":"شخص برای مصاحبه انتخاب شده است.","Der Eingang sagt noch nichts über Auswahl oder Einstellungsentscheidung aus.":"دریافت هنوز چیزی دربارهٔ انتخاب یا تصمیم استخدام نمی‌گوید.","Lies die Zusammenfassung im Portal vor dem Absenden noch einmal gegen deine Dateien.":"خلاصه در پورتال را پیش از فرستادن یک بار دیگر با فایل‌های خود مقایسه کنید.","Vor dem Absenden innehalten":"مکث پیش از فرستادن","Yasin: „Alle Dateien sind hochgeladen. Ist die Bewerbung schon weg?“ Freundin: „Siehst du eine Versandbestätigung?“ Yasin: „Nein, hier steht Entwurf.“ Freundin: „Dann fehlt noch die Freigabe zum Absenden.“ Yasin: „Ich prüfe vorher die Felder und Dokumente. Erst danach drücke ich auf Bewerbung senden.“":"یاسین: «همهٔ فایل‌ها بارگذاری شده‌اند. درخواست رفته است؟» دوستش: «یک تأیید فرستادن می‌بینی؟» یاسین: «نه، اینجا نوشته Entwurf.» دوستش: «پس هنوز تأیید فرستادن کم است.» یاسین: «پیش از آن خانه‌ها و اسناد را بررسی می‌کنم. فقط بعد از آن روی Bewerbung senden (فرستادن درخواست) فشار می‌دهم.»","Formular und Datei konsistent halten":"یکسان نگه داشتن فورم و فایل","Wenn Zeitraum, Telefonnummer oder Stellenkennziffer sowohl im Formular als auch im Lebenslauf stehen, müssen sie zusammenpassen. Automatisch erkannte Daten können falsch übernommen werden. Kontrolliere besonders Namen und Datumsangaben. Ein hochgeladenes Dokument korrigiert einen falschen Formulareintrag nicht immer automatisch. Prüfe beides getrennt.":"اگر مدت، شمارهٔ تیلفون یا شمارهٔ اعلان هم در فورم و هم در رزومه باشد، باید با هم جور باشند. داده‌های خودکار تشخیص‌داده‌شده ممکن است اشتباه نوشته شوند. به‌خصوص نام‌ها و تاریخ‌ها را بررسی کنید. یک سند بارگذاری‌شده همیشه یک نوشتهٔ اشتباه فورم را خودکار اصلاح نمی‌کند. هر دو را جدا بررسی کنید.","Technische Vorgaben lesen":"خواندن شرط‌های فنی","Ein Entwurf ist eine gespeicherte, noch nicht abgesendete Bewerbung. Ein Upload legt zunächst nur Dateien im Portal ab. Lies vor dem Absenden die Hinweise zu Format und Dateigröße. Prüfe Fehlermeldungen und behebe sie. Klicke erst danach auf „Bewerbung senden“. Kontrolliere anschließend den neuen Status.":"یک پیش‌نویس یک درخواست ذخیره‌شده است که هنوز فرستاده نشده. یک بارگذاری اول فقط فایل‌ها را در پورتال می‌گذارد. پیش از فرستادن راهنمایی‌های قالب و اندازهٔ فایل را بخوانید. پیام‌های خطا را بررسی و رفع کنید. فقط بعد از آن روی „Bewerbung senden“ کلیک کنید. بعد وضعیت تازه را بررسی کنید.","Den tatsächlichen Ausgang dokumentieren":"ثبت فرستادن واقعی","Notiere Stelle, Datum und gegebenenfalls eine bestätigte Bewerbungsnummer nach dem Absenden. Ein Entwurf ist noch keine gesendete Bewerbung. Eine Eingangsbestätigung belegt den Eingang, aber nicht die Auswahl für ein Gespräch. Bleibt der Ausgang unklar, prüfe den Portalstatus oder den offiziellen Kontakt, bevor du denselben Vorgang mehrfach einreichst.":"بعد از فرستادن، کار، تاریخ و در صورت وجود یک شمارهٔ تأییدشدهٔ درخواست را یادداشت کنید. یک پیش‌نویس هنوز درخواست فرستاده‌شده نیست. یک تأیید دریافت، دریافت را ثابت می‌کند، اما نه انتخاب برای مصاحبه را. اگر فرستادن نامعلوم ماند، وضعیت پورتال یا تماس رسمی را بررسی کنید، پیش از اینکه همان روند را چند بار بفرستید.","Den Portalstatus ergänzen":"کامل کردن وضعیت پورتال","Setze „Entwurf“ und „Eingang“ ein.":"„Entwurf“ و „Eingang“ (دریافت) را بگذارید.","Unterscheide gespeicherten Stand und erhaltene Unterlagen.":"وضعیت ذخیره‌شده و اسناد دریافت‌شده را جدا کنید.","Der Status dokumentiert jeweils ein anderes Ereignis.":"این وضعیت هر بار یک رویداد دیگر را ثبت می‌کند.","Noch nicht abgesendet: ___.":"Noch nicht abgesendet: ___. (هنوز فرستاده نشده: ___.)","Durch Bestätigung belegter Empfang: ___.":"Durch Bestätigung belegter Empfang: ___. (دریافت ثابت‌شده با تأیید: ___.)","Portalschritte zuordnen":"وصل کردن قدم‌های پورتال","Ordne Handlung und Ergebnis.":"کار و نتیجه را وصل کنید.","Vorbereitung und Empfang liegen auf verschiedenen Seiten des Versands.":"آماده‌سازی و دریافت در دو طرف فرستادن هستند.","Die Schritte bauen aufeinander auf, sind aber nicht austauschbar.":"این قدم‌ها بر هم ساخته می‌شوند، اما قابل جابه‌جایی نیستند.","Datei auswählen":"انتخاب فایل","Bewerbung senden":"فرستادن درخواست","Bestätigung lesen":"خواندن تأیید","Den aktuellen Status hören":"شنیدن وضعیت فعلی","Welchen Status zeigt das Portal vor Yasins Prüfung?":"پورتال پیش از بررسی یاسین کدام وضعیت را نشان می‌دهد؟","Gefragt ist der sichtbare Status, nicht Yasins Vermutung.":"وضعیت قابل دید پرسیده شده، نه حدس یاسین.","Das Portal kennzeichnet den noch nicht abgesendeten Entwurf.":"پورتال پیش‌نویس هنوز فرستاده‌نشده را علامت می‌زند.","Den Einreichungsweg dokumentieren":"ثبت راه فرستادن","Schreibe vier Sätze: Entwurf, Datenvergleich, Absenden und Nachweis.":"چهار جمله بنویسید: پیش‌نویس، مقایسهٔ داده‌ها، فرستادن و مدرک.","Beschreibe den tatsächlichen Ablauf, nicht nur die gewünschte Wirkung.":"روند واقعی را توصیف کنید، نه فقط اثر دلخواه را.","Die Dokumentation verhindert einen voreiligen Status „versandt“.":"این ثبت از یک وضعیت عجولانهٔ «فرستاده‌شده» جلوگیری می‌کند.","Bleibt der Entwurf vom Versand getrennt?":"آیا پیش‌نویس از فرستادن جدا می‌ماند؟","Prüfst du Formular und Anhänge vor dem Absenden?":"آیا فورم و ضمیمه‌ها را پیش از فرستادن بررسی می‌کنید؟","Nennst du die ausdrückliche Versandhandlung?":"آیا کار صریح فرستادن را نام می‌برید؟","Belegst du den Eingang statt ihn vorauszusetzen?":"آیا دریافت را ثابت می‌کنید، به جای اینکه آن را فرض کنید؟","Entwurf, Absenden und Eingang sind verschiedene Ereignisse.":"پیش‌نویس، فرستادن و دریافت رویدادهای مختلفی هستند.","Ein Parser kann Daten erkennen und dabei Fehler machen.":"یک تحلیلگر (Parser) ممکن است داده‌ها را تشخیص دهد و در این میان اشتباه کند.","Bewerbungen prüfen und Versionen unterscheiden":"بررسی درخواست‌ها و جدا کردن نسخه‌ها","Du führst eine letzte Inhaltskontrolle durch und bewahrst die versandte Fassung eindeutig auf.":"شما یک بررسی پایانی محتوا انجام می‌دهید و نسخهٔ فرستاده‌شده را روشن نگه می‌دارید.","Rechtschreibprüfung als Inhaltsprüfung behandeln":"بررسی املا را بررسی محتوا دانستن","Falsch: „Der Firmenname ist richtig, weil er nicht unterstrichen ist.“ Richtig: Den Namen mit der tatsächlichen Ausschreibung vergleichen.":"اشتباه: «نام شرکت درست است، چون زیرش خط کشیده نشده.» درست: نام را با اعلان واقعی مقایسه کنید.","Versandte Fassung durch Entwurf ersetzen":"جایگزین کردن نسخهٔ فرستاده‌شده با پیش‌نویس","Falsch: Spätere Änderungen so speichern, als seien sie bereits versandt worden. Richtig: Entwurf und tatsächlich eingereichte Fassung getrennt halten.":"اشتباه: تغییرهای بعدی را طوری ذخیره کنید که انگار از قبل فرستاده شده‌اند. درست: پیش‌نویس و نسخهٔ واقعاً فرستاده‌شده را جدا نگه دارید.","Welchen Fehler enthält Majas Entwurf?":"پیش‌نویس مایا کدام خطا را دارد؟","Der Firmenname ist zwischen Betreff und Text widersprüchlich.":"نام شرکت بین موضوع و متن متناقض است.","Die Dateiform ist falsch, weil ein PDF verwendet wird.":"قالب فایل اشتباه است، چون PDF به کار رفته.","Die Kennziffer ist nachweislich falsch, obwohl sie noch nicht geprüft wurde.":"شمارهٔ اعلان ثابت‌شده اشتباه است، با اینکه هنوز بررسی نشده.","Firma West und Firma Ost passen im selben Schreiben nicht zur gleichen Bewerbung.":"Firma West و Firma Ost در یک نامه با یک درخواست جور نیستند.","Warum reicht eine Rechtschreibprüfung nicht?":"چرا بررسی املا کافی نیست؟","Sie prüft automatisch den Bezug zur aktuellen Anzeige.":"خودکار ربط با اعلان فعلی را بررسی می‌کند.","Sie erkennt jeden falschen Empfänger anhand des Dateinamens.":"هر گیرندهٔ اشتباه را از روی نام فایل می‌شناسد.","Ein falscher Firmenname kann korrekt geschrieben sein.":"یک نام اشتباه شرکت ممکن است درست نوشته شده باشد.","Inhaltliche Zuordnung wird durch fehlerfreie Schreibweise nicht bewiesen.":"ربط محتوایی با املای بی‌خطا ثابت نمی‌شود.","Welche Datei bleibt für die Nachbereitung wichtig?":"کدام فایل برای پیگیری بعدی مهم می‌ماند؟","Nur die zuletzt gespeicherte spätere Änderung.":"فقط آخرین تغییر ذخیره‌شدهٔ بعدی.","Die tatsächlich versandte Fassung.":"نسخهٔ واقعاً فرستاده‌شده.","Nur die ursprüngliche Vorlage vor der Anpassung.":"فقط قالب اصلی پیش از تطبیق.","Sie zeigt, auf welche Angaben sich ein späteres Gespräch beziehen kann.":"نشان می‌دهد که یک مصاحبهٔ بعدی ممکن است به کدام معلومات اشاره کند.","Kontrolliere Namen, Stelle, Zahlen und Anhänge in einer eigenen Schlussrunde.":"نام‌ها، کار، عددها و ضمیمه‌ها را در یک دور پایانی جداگانه بررسی کنید.","Einen Vorlagenfehler entdecken":"کشف یک خطای قالب","Maja: „Mein Anschreiben ist fertig.“ Freund: „Im Betreff steht Firma West, im Text Firma Ost.“ Maja: „Ich habe die Vorlage zu schnell geändert.“ Freund: „Prüfe außerdem die Stelle und Kennziffer.“ Maja: „Danach öffne ich das PDF und lege genau diese Fassung im Ordner der Bewerbung ab.“":"مایا: «نامهٔ درخواستم آماده است.» دوستش: «در موضوع Firma West نوشته و در متن Firma Ost.» مایا: «قالب را خیلی عجولانه تغییر دادم.» دوستش: «کار و شمارهٔ اعلان را هم بررسی کن.» مایا: «بعد PDF را باز می‌کنم و دقیقاً همین نسخه را در پوشهٔ درخواست می‌گذارم.»","Inhalt vor Gestaltung prüfen":"بررسی محتوا پیش از طراحی","Lies den Text einmal nur auf Aussage und Richtigkeit. Stimmen Firma, Stelle, Kontakt und Erfahrungen? Eine zweite Runde prüft Sprache und Lesbarkeit. Verlasse dich nicht allein auf eine Rechtschreibprüfung: Sie erkennt einen korrekt geschriebenen, aber falschen Firmennamen nicht zuverlässig. Prüfe besonders übernommene Vorlagenreste.":"متن را یک بار فقط از نظر گفته و درستی بخوانید. آیا شرکت، کار، تماس و تجربه‌ها درست‌اند؟ یک دور دوم زبان و خوانایی را بررسی می‌کند. فقط به بررسی املا اعتماد نکنید: یک نام شرکت درست‌نوشته اما اشتباه را به‌طور قابل اعتماد نمی‌شناسد. به‌خصوص باقی‌مانده‌های قالب را بررسی کنید.","Dateistände verständlich benennen":"نام‌گذاری قابل فهم نسخه‌های فایل","Bewahre die versandte Fassung mit Datum und Stelle auf. Ein später geänderter Entwurf ist eine andere Fassung. Überschreibe deshalb nicht die Datei, die deinen tatsächlichen Versand belegt. Musst du etwas nachreichen, notiere den Inhalt und das neue Datum. So kannst du im Gespräch erklären, welche Unterlagen der Betrieb erhalten hat.":"نسخهٔ فرستاده‌شده را با تاریخ و کار نگه دارید. یک پیش‌نویس که بعداً تغییر کرده نسخهٔ دیگری است. به همین دلیل فایلی را که فرستادن واقعی شما را ثابت می‌کند بازنویسی نکنید. اگر باید چیزی را بعداً بفرستید، محتوا و تاریخ تازه را یادداشت کنید. به این ترتیب می‌توانید در مصاحبه توضیح دهید که شرکت کدام اسناد را گرفته است.","Eine kurze Endkontrolle anwenden":"به کار بردن یک بررسی پایانی کوتاه","Öffne alle endgültigen Anhänge und prüfe Reihenfolge, Vollständigkeit und den Bezug zum Empfänger. Wenn möglich, lass eine andere Person den Text auf Verständnis lesen, ohne mehr persönliche Daten als nötig weiterzugeben. Die Entscheidung zum Absenden erfolgt nach dieser Prüfung. Eine Checkliste hilft nur, wenn jeder Punkt tatsächlich kontrolliert und nicht bloß abgehakt wird.":"همهٔ ضمیمه‌های نهایی را باز کنید و ترتیب، کامل بودن و ربط با گیرنده را بررسی کنید. اگر ممکن است، بگذارید شخص دیگری متن را از نظر قابل فهم بودن بخواند، بدون اینکه داده‌های شخصی بیشتر از لازم بدهید. تصمیم فرستادن بعد از این بررسی گرفته می‌شود. یک چک‌لست فقط وقتی کمک می‌کند که هر نکته واقعاً بررسی شود و فقط علامت زده نشود.","Eine Schlusskontrolle ergänzen":"کامل کردن یک بررسی پایانی","Setze „Firma“ und „Fassung“ ein.":"„Firma“ (شرکت) و „Fassung“ (نسخه) را بگذارید.","Prüfe Empfängerbezug und Dokumentstand.":"ربط با گیرنده و وضعیت سند را بررسی کنید.","Beide Kontrollen verhindern unterschiedliche Vorlagen- und Versionsfehler.":"هر دو بررسی از خطاهای مختلف قالب و نسخه جلوگیری می‌کنند.","Betreff und Text müssen dieselbe ___ nennen.":"Betreff und Text müssen dieselbe ___ nennen. (موضوع و متن باید یک ___ را نام ببرند.)","Ich bewahre die versandte ___ auf.":"Ich bewahre die versandte ___ auf. (___ فرستاده‌شده را نگه می‌دارم.)","Kontrollpunkte sortieren":"مرتب کردن نکته‌های بررسی","Ordne das Beispiel der Prüfung zu.":"مثال را به بررسی وصل کنید.","Ein Dokument kann mehrere verschiedene Fehlerarten enthalten.":"یک سند ممکن است چند نوع مختلف خطا داشته باشد.","Die Kategorien helfen bei einer gezielten Schlussprüfung.":"این دسته‌ها به یک بررسی پایانی هدفمند کمک می‌کنند.","falscher Firmenname":"نام اشتباه شرکت","abgeschnittener Absatz":"پاراگراف بریده‌شده","fehlendes Zertifikat":"گواهی‌نامهٔ کم","Den alten Firmennamen hören":"شنیدن نام قدیمی شرکت","Welcher Firmenname ist versehentlich im Text stehen geblieben? Antworte mit einem Wort.":"کدام نام شرکت به اشتباه در متن باقی مانده؟ با یک کلمه جواب دهید.","Gesucht ist der Vorlagenrest.":"باقی‌ماندهٔ قالب پرسیده شده است.","Der falsche stehen gebliebene Name lautet Ost.":"نام اشتباه باقی‌مانده Ost است.","Eine Endkontrolle dokumentieren":"ثبت یک بررسی پایانی","Schreibe drei Sätze über Empfängerprüfung, PDF-Kontrolle und Ablage der versandten Fassung.":"سه جمله دربارهٔ بررسی گیرنده، بررسی PDF و ذخیرهٔ نسخهٔ فرستاده‌شده بنویسید.","Die Kontrolle soll eine durchgeführte Handlung beschreiben.":"بررسی باید کاری را توصیف کند که انجام شده است.","Die drei Sätze sichern Zuordnung, Qualität und Nachvollziehbarkeit.":"این سه جمله ربط، کیفیت و قابل پیگیری بودن را تضمین می‌کنند.","Prüfst du Empfänger, Stelle und Kennziffer?":"آیا گیرنده، کار و شمارهٔ اعلان را بررسی می‌کنید؟","Öffnest du die endgültigen Dateien tatsächlich?":"آیا فایل‌های نهایی را واقعاً باز می‌کنید؟","Berücksichtigst du Lesbarkeit und vollständige Anlagen?":"آیا خوانایی و کامل بودن ضمیمه‌ها را در نظر می‌گیرید؟","Unterscheidest du versandte Fassung und spätere Entwürfe?":"آیا نسخهٔ فرستاده‌شده و پیش‌نویس‌های بعدی را جدا می‌کنید؟","Ein sprachlich korrektes Wort kann inhaltlich der falsche Firmenname sein.":"یک کلمهٔ از نظر زبانی درست ممکن است از نظر محتوا نام اشتباه شرکت باشد.","Die versandte Fassung bleibt als eigener Stand nachvollziehbar.":"نسخهٔ فرستاده‌شده به عنوان یک وضعیت جداگانه قابل پیگیری می‌ماند.","Rückmeldungen sachlich bearbeiten":"رسیدگی واقع‌بینانه به جواب‌ها","Du beantwortest Nachfragen, ordnest Statusmeldungen richtig ein und bereitest den nächsten Schritt vor.":"شما به پرسش‌ها جواب می‌دهید، پیام‌های وضعیت را درست مرتب می‌کنید و قدم بعدی را آماده می‌کنید.","Nachforderung als Zusage lesen":"درخواست سند اضافی را قبولی خواندن","Falsch: „Ich bin eingestellt“, weil ein Zertifikat nachgefordert wird. Richtig: Es fehlt eine Unterlage im laufenden Verfahren.":"اشتباه: «استخدام شدم»، چون یک گواهی‌نامه دوباره خواسته می‌شود. درست: در روند جاری یک سند کم است.","Nicht vorhandenen Beleg ankündigen":"اعلام یک مدرک ناموجود","Falsch: Ein Zertifikat als beigefügt bezeichnen, das nicht vorliegt. Richtig: Vorhandene Unterlagen prüfen und die Lücke ehrlich klären.":"اشتباه: یک گواهی‌نامه را ضمیمه‌شده بنامید که وجود ندارد. درست: اسناد موجود را بررسی کنید و کمبود را صادقانه روشن کنید.","Was verlangt die Personalstelle?":"بخش کارکنان چه می‌خواهد؟","Den bisherigen Termin für ein Gespräch absagen.":"لغو وقت قبلی مصاحبه.","Das genannte Kurszertifikat bis Freitag.":"گواهی‌نامهٔ کورس نام‌برده تا جمعه.","Einen neuen Lebenslauf ohne das Zertifikat senden.":"فرستادن یک رزومهٔ تازه بدون گواهی‌نامه.","Die Nachricht fordert einen konkreten Nachweis innerhalb einer genannten Frist.":"این پیام یک مدرک مشخص را در یک مهلت نام‌برده می‌خواهد.","Welche Aussage zum Status ist korrekt?":"کدام جمله دربارهٔ وضعیت درست است؟","Das Bewerbungsverfahren läuft mit einer Nachforderung weiter.":"روند درخواست با یک درخواست سند اضافی ادامه دارد.","Die Bewerbung ist endgültig erfolgreich abgeschlossen.":"درخواست به‌طور نهایی موفق تمام شده است.","Die fehlende Unterlage wurde bereits als vorhanden bestätigt.":"سند کم از قبل موجود تأیید شده است.","Eine Nachforderung ist weder Einstellungszusage noch Abschluss des Verfahrens.":"درخواست سند اضافی نه قبولی استخدام است و نه پایان روند.","Was tust du, wenn das Zertifikat nicht vorliegt?":"اگر گواهی‌نامه وجود ندارد چه می‌کنید؟","Einen ähnlichen Nachweis ohne Erläuterung als gefordertes Zertifikat senden.":"یک مدرک مشابه را بدون توضیح به عنوان گواهی‌نامهٔ خواسته‌شده می‌فرستید.","Den Versand zusagen, ohne das Dokument vorher zu prüfen.":"فرستادن را وعده می‌دهید، بدون اینکه سند را پیش از آن بررسی کنید.","Die Lücke ehrlich erklären und das Vorgehen klären.":"کمبود را صادقانه توضیح می‌دهید و راه کار را روشن می‌کنید.","Eine nachvollziehbare Klärung vermeidet falsche Qualifikationsangaben.":"یک روشن‌سازی قابل پیگیری از معلومات اشتباه صلاحیت جلوگیری می‌کند.","Lies jede Rückmeldung auf konkrete Handlung, Termin und benötigte Unterlage, bevor du reagierst.":"هر جواب را از نظر کار مشخص، وقت و سند لازم بخوانید، پیش از اینکه واکنش نشان دهید.","Eine Nachforderung verstehen":"فهمیدن یک درخواست سند اضافی","Personalstelle: „Vielen Dank. Bitte reichen Sie das im Lebenslauf genannte Kurszertifikat bis Freitag nach.“ Eren: „Ist das schon eine Zusage?“ Freundin: „Nein, es ist eine Nachforderung.“ Eren: „Dann prüfe ich den Kontakt und sende das zutreffende Zertifikat über den vereinbarten Weg.“":"بخش کارکنان: „Vielen Dank. Bitte reichen Sie das im Lebenslauf genannte Kurszertifikat bis Freitag nach.“ (سپاس. لطفاً گواهی‌نامهٔ کورس نام‌برده در رزومه را تا جمعه بفرستید.) ارن: «این از همین حالا قبولی است؟» دوستش: «نه، یک درخواست سند اضافی (Nachforderung) است.» ارن: «پس تماس را بررسی می‌کنم و گواهی‌نامهٔ درست را از راه توافق‌شده می‌فرستم.»","Status und Handlungsbedarf trennen":"جدا کردن وضعیت و نیاز به کار","Eine Eingangsbestätigung meldet den Empfang. Eine Nachforderung verlangt zusätzliche Angaben. Eine Einladung nennt einen weiteren Auswahltermin. Keine dieser Meldungen allein bedeutet eine Einstellung. Markiere in der Nachricht, was du konkret tun sollst, welche Frist gilt und welcher Weg genannt ist. Kläre einen widersprüchlichen Termin über den offiziellen Kontakt.":"یک تأیید دریافت دریافت را اعلام می‌کند. یک درخواست سند اضافی معلومات بیشتر می‌خواهد. یک دعوت یک وقت دیگر انتخاب را نام می‌برد. هیچ کدام از این پیام‌ها به تنهایی به معنای استخدام نیست. در پیام علامت بزنید که مشخصاً چه باید بکنید، کدام مهلت اعتبار دارد و کدام راه نام برده شده است. یک وقت متناقض را از راه تماس رسمی روشن کنید.","Höflich antworten und ehrlich bleiben":"جواب مؤدبانه و صادقانه","Antworte nur mit Angaben, die stimmen. Eine mögliche Antwort lautet: „Vielen Dank. Ich reiche das angeforderte Zertifikat über das Portal nach.“ Prüfe vorher, ob die Datei vorliegt. Fehlt der Nachweis, sage das offen. Frage, welcher andere Beleg oder nächste Schritt möglich ist. Versprich keine Datei, die du nicht besitzt.":"فقط با معلوماتی جواب دهید که درست است. یک جواب ممکن این است: „Vielen Dank. Ich reiche das angeforderte Zertifikat über das Portal nach.“ (سپاس. گواهی‌نامهٔ خواسته‌شده را از راه پورتال می‌فرستم.) پیش از آن بررسی کنید که آیا فایل وجود دارد. اگر مدرک نیست، آن را آشکارا بگویید. بپرسید که کدام مدرک دیگر یا قدم بعدی ممکن است. فایلی را که ندارید وعده ندهید.","Den weiteren Verlauf dokumentieren":"ثبت ادامهٔ روند","Notiere die tatsächlich erfolgte Nachreichung und bewahre die Bestätigung auf. Bei einer Absage kannst du deine Unterlagen und Auswahlkriterien überprüfen; sie beweist nicht, dass jede andere Bewerbung aussichtslos ist. Im anschließenden Kurs bereitest du eine Einladung und die ersten Arbeitstage vor. Dein Bewerbungsstatus bleibt bis dahin so konkret wie die vorhandenen Nachrichten.":"فرستادن بعدی واقعی را یادداشت کنید و تأیید را نگه دارید. با یک جواب منفی می‌توانید اسناد و معیارهای انتخاب خود را بررسی کنید؛ این ثابت نمی‌کند که هر درخواست دیگری بی‌نتیجه است. در کورس بعدی یک دعوت و روزهای اول کار را آماده می‌کنید. وضعیت درخواست شما تا آن وقت به اندازهٔ پیام‌های موجود مشخص می‌ماند.","Den Handlungsbedarf ergänzen":"کامل کردن نیاز به کار","Setze „Zertifikat“ und „Freitag“ ein.":"„Zertifikat“ و „Freitag“ (جمعه) را بگذارید.","Lies Unterlage und Frist getrennt heraus.":"سند و مهلت را جدا بیرون بکشید.","Die Nachricht benennt beides ausdrücklich.":"پیام هر دو را صریحاً نام می‌برد.","Nachgefordert wird das ___.":"Nachgefordert wird das ___. (___ دوباره خواسته می‌شود.)","Die genannte Frist endet am ___.":"Die genannte Frist endet am ___. (مهلت نام‌برده روز ___ تمام می‌شود.)","Rückmeldungen unterscheiden":"جدا کردن جواب‌ها","Ordne die Meldung ihrer Bedeutung zu.":"پیام را به معنای آن وصل کنید.","Eine Auswahlentscheidung wird dadurch noch nicht ersetzt.":"یک تصمیم انتخاب با این هنوز جایگزین نمی‌شود.","Die Kategorien zeigen den jeweiligen nächsten Schritt im Verfahren.":"این دسته‌ها قدم بعدی هر بخش روند را نشان می‌دهند.","Eingang bestätigt":"دریافت تأیید شد","Zertifikat nachreichen":"فرستادن بعدی گواهی‌نامه","Termin zum Gespräch":"وقت مصاحبه","Die Frist verstehen":"فهمیدن مهلت","Bis zu welchem Tag soll Eren den Nachweis nachreichen?":"ارن تا کدام روز باید مدرک را بفرستد؟","Gesucht ist der letzte genannte Tag für die Unterlage.":"آخرین روز نام‌برده برای سند پرسیده شده است.","Die Frist der Nachforderung lautet Freitag.":"مهلت درخواست سند اضافی جمعه (Freitag) است.","Eine Nachforderung beantworten":"جواب دادن به یک درخواست سند اضافی","Schreibe eine kurze Antwort: Nachricht erhalten, zutreffendes Zertifikat bis Freitag über den vereinbarten Portalweg nachreichen, keine Zusage behaupten.":"یک جواب کوتاه بنویسید: پیام دریافت شد، گواهی‌نامهٔ درست تا جمعه از راه پورتال توافق‌شده فرستاده می‌شود، هیچ قبولی ادعا نشود.","Prüfe vor dieser Zusage, ob der Nachweis tatsächlich vorhanden ist.":"پیش از این وعده بررسی کنید که آیا مدرک واقعاً وجود دارد.","Die Antwort bleibt bei der konkreten Nachreichung und dem belegbaren Verfahrensstand.":"این جواب به فرستادن مشخص و وضعیت قابل اثبات روند بسنده می‌کند.","Beziehst du dich auf die nachgeforderte Unterlage?":"آیا به سند دوباره خواسته‌شده اشاره می‌کنید؟","Nennst du die Frist bis Freitag?":"آیا مهلت تا جمعه را نام می‌برید؟","Verwendest du den vereinbarten Einreichungsweg?":"آیا راه فرستادن توافق‌شده را به کار می‌برید؟","Vermeidest du eine erfundene Einstellungszusage?":"آیا از یک قبولی ساختگی استخدام پرهیز می‌کنید؟","Eine Nachforderung ist ein Arbeitsauftrag innerhalb des Bewerbungsverfahrens.":"یک درخواست سند اضافی یک کار در داخل روند درخواست است.","Eine Antwort nennt nur Unterlagen, die tatsächlich eingereicht werden.":"یک جواب فقط اسنادی را نام می‌برد که واقعاً فرستاده می‌شوند."};})(typeof window!=="undefined"?window:globalThis);
